changeSet.sql:
-- 1. Bổ sung các cột schema phục vụ phân loại sản phẩm, bảo hành, tính giá và khuyến mãi ALTER TABLE public.product_categories ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE public.warranty_policies ADD COLUMN IF NOT EXISTS category_id uuid; ALTER TABLE public.warranty_policies ADD COLUMN IF NOT EXISTS duration_months integer DEFAULT 12; ALTER TABLE public.warranty_policies ADD COLUMN IF NOT EXISTS terms text; ALTER TABLE public.warranty_policies ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS has_weight_sensor boolean DEFAULT false;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS size text; ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS capacity_liter integer; ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS warranty_months integer DEFAULT 12; ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS has_weight_sensor boolean DEFAULT false; ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS is_active boolean DEFAULT true;
ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS discount_type varchar(20) DEFAULT 'percentage'; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS discount_value numeric DEFAULT 0; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS min_order_value numeric DEFAULT 0; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS max_discount numeric; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS usage_limit integer DEFAULT 100; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS used_count integer DEFAULT 0; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now(); ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS discount_percent numeric; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS discount_amount numeric; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS min_order_amount numeric; ALTER TABLE public.promotions ADD COLUMN IF NOT EXISTS max_discount_amount numeric;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS subtotal numeric; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS discount_amount numeric DEFAULT 0; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS voucher_code text;
-- 2. Seed 3 Danh mục / Loại sản phẩm chính INSERT INTO public.product_categories(id, name, slug, description) VALUES ( '11111111-1111-1111-1111-111111111101', 'Tủ Nhận Hàng Thông Minh SmartBox', 'tu-nhan-hang-thong-minh', 'Các dòng tủ giao nhận bưu kiện thông minh cho nhà phố, biệt thự và chung cư (SmartBox Standard, Pro, Mini).' ), ( '11111111-1111-1111-1111-111111111102', 'Linh Kiện Thay Thế và Sửa Chữa', 'linh-kien-thay-the', 'Phụ tùng, bo mạch điện tử, khóa chốt và cảm biến thay thế định kỳ hoặc khắc phục sự cố hỏng hóc cho tủ SmartBox.' ), ( '11111111-1111-1111-1111-111111111103', 'Phụ Kiện và Tiện Ích Mở Rộng', 'phu-kien-tien-ich', 'Các phụ kiện lắp đặt bổ sung, nâng cấp tiện ích và bảo vệ tủ ngoài trời (mái che mưa, chân đế nâng cao, đèn LED cảm biến).' ) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, description = EXCLUDED.description;
-- 3. Seed Chính sách bảo hành theo từng loại sản phẩm INSERT INTO public.warranty_policies(id, category_id, duration_months, terms) VALUES ( '99999999-9999-9999-9999-999999999901', '11111111-1111-1111-1111-111111111101', 12, 'Bảo hành chính hãng 12-24 tháng cho toàn bộ thân vỏ, bản lề, khóa điện tử và hệ thống điều khiển SmartBox.' ), ( '99999999-9999-9999-9999-999999999902', '11111111-1111-1111-1111-111111111102', 6, 'Bảo hành 6 tháng 1 đổi 1 đối với các linh kiện điện tử, bo mạch, cảm biến và khóa chốt thay thế.' ), ( '99999999-9999-9999-9999-999999999903', '11111111-1111-1111-1111-111111111103', 6, 'Bảo hành 6 tháng cho phụ kiện kim khí, mái che chống rỉ sét và đèn LED cảm biến.' ) ON CONFLICT (id) DO UPDATE SET category_id = EXCLUDED.category_id, duration_months = EXCLUDED.duration_months, terms = EXCLUDED.terms;
-- 4. Seed sản phẩm và biến thể đã được loại bỏ (sẵn sàng cho dữ liệu thực)
-- 6. Seed Khuyến mãi / Vouchers INSERT INTO public.promotions( id, code, description, discount_type, discount_value, min_order_value, max_discount, start_date, end_date, usage_limit, used_count, is_active ) VALUES ( '44444444-4444-4444-4444-444444444401', 'SMARTBOX10', 'Giảm 10% tối đa 500.000 VNĐ cho đơn hàng từ 2.000.000 VNĐ', 'percentage', 10, 2000000, 500000, '2026-01-01 00:00:00+07', '2027-12-31 23:59:59+07', 500, 0, true ), ( '44444444-4444-4444-4444-444444444402', 'CHAOMUNG', 'Giảm ngay 200.000 VNĐ cho đơn hàng SmartBox từ 1.500.000 VNĐ', 'fixed_amount', 200000, 1500000, 200000, '2026-01-01 00:00:00+07', '2027-12-31 23:59:59+07', 1000, 0, true ), ( '44444444-4444-4444-4444-444444444403', 'FREESHIP', 'Miễn phí vận chuyển và lắp đặt 100.000 VNĐ cho đơn từ 3.000.000 VNĐ', 'fixed_amount', 100000, 3000000, 100000, '2026-01-01 00:00:00+07', '2027-12-31 23:59:59+07', 200, 0, true ) ON CONFLICT (id) DO UPDATE SET code = EXCLUDED.code, description = EXCLUDED.description, discount_type = EXCLUDED.discount_type, discount_value = EXCLUDED.discount_value, min_order_value = EXCLUDED.min_order_value, max_discount = EXCLUDED.max_discount, is_active = EXCLUDED.is_active;
-- Đồng bộ các cột cũ nếu có UPDATE public.promotions SET discount_percent = CASE WHEN discount_type = 'percentage' THEN discount_value ELSE NULL END, discount_amount = CASE WHEN discount_type = 'fixed_amount' THEN discount_value ELSE NULL END, min_order_amount = min_order_value, max_discount_amount = max_discount WHERE code IN ('SMARTBOX10', 'CHAOMUNG', 'FREESHIP');
